#include<iostream>#include<vector>#include<string>using namespace std; int main() {    string s;    cin >> s;    int n = s.length();    vector<int> freq(4,0);    int cntPlus = 0;    for(char ch : s){        if(isdigit(ch))            freq[ch - '0']++;        if(ch == '+')            cntPlus++;    }    string res = "";    for(int i=1; i<=3; i++){        while(freq[i] > 0){            res += to_string(i);            freq[i]--;            if(cntPlus > 0){                res += "+";                cntPlus--;            }        }    }    cout << res;    return 0;}